package glitch

import data.glitch_lib

# Check for public bind address (0.0.0.0) in Hash values
# This handles nested structures like Hash within Hash
check_hash_public_bind(value) {
    value.ir_type == "Hash"
    entry := value.value[_]
    key_str := entry.key.value
    regex.match("(?i)(bind.*address|bind_address|ip$|address$|host$)", key_str)
    val_str := entry.value.value
    val_str == "0.0.0.0"
} else {
    value.ir_type == "Hash"
    entry := value.value[_]
    check_hash_public_bind(entry.value)
}

# Check for public bind address in Variable nodes
check_var_public_bind(var) {
    var.ir_type == "Variable"
    check_hash_public_bind(var.value)
} else {
    var.ir_type == "Variable"
    var.value.ir_type == "String"
    var.value.value == "0.0.0.0"
    regex.match("(?i)(bind.*address|bind_address|ip$|address$|host$)", var.name)
}

# Check for public bind address in Attribute nodes
check_attr_public_bind(attr) {
    attr.ir_type == "Attribute"
    attr.value.ir_type == "String"
    attr.value.value == "0.0.0.0"
    regex.match("(?i)(bind.*address|bind_address|ip$|address$|host$)", attr.name)
} else {
    attr.ir_type == "Attribute"
    check_hash_public_bind(attr.value)
}

