# Helper rule to check if a key is IP-related
key_is_ip_related(key) {
    key.ir_type == "VariableReference"
    regex.match("(?i)(ip|address|bind|host|addr|bind-address|bind_address)", key.value)
} else {
    key.ir_type == "String"
    regex.match("(?i)(ip|address|bind|host|addr|bind-address|bind_address)", key.value)
}

